-- Data demo hanya dimasukkan bila profile local memberikan placeholder seed_enabled=true.
-- Migration tetap dicatat Flyway pada dev/prod, tetapi seluruh INSERT di bawah tidak menghasilkan baris.

INSERT INTO app_users (id, name, email, password_hash, created_at)
SELECT CAST('10000000-0000-0000-0000-000000000001' AS UUID),
       'Admin Demo',
       'demo@remiyu.local',
       '$2a$10$dt7/AYqV0C7Ob142Rqa6Rev3vJRJsg9902K1779uMFguSuyqfo.Ai',
       CURRENT_TIMESTAMP
WHERE '${seed_enabled}' = 'true'
  AND NOT EXISTS (SELECT 1 FROM app_users WHERE email = 'demo@remiyu.local');

INSERT INTO workspaces (id, owner_id, name, platform, account, connection_status, billing_status, invite_token, created_at)
SELECT CAST('10000000-0000-0000-0000-000000000010' AS UUID),
       (SELECT id FROM app_users WHERE email = 'demo@remiyu.local'),
       'Operasional Peluncuran Remiyu',
       'WHATSAPP',
       '+6281212345678',
       'CONNECTED',
       'FREE',
       CAST('10000000-0000-0000-0000-000000000011' AS UUID),
       CURRENT_TIMESTAMP
WHERE '${seed_enabled}' = 'true'
  AND EXISTS (SELECT 1 FROM app_users WHERE email = 'demo@remiyu.local')
  AND NOT EXISTS (SELECT 1 FROM workspaces WHERE id = CAST('10000000-0000-0000-0000-000000000010' AS UUID));

INSERT INTO workspace_members (workspace_id, user_id, role)
SELECT CAST('10000000-0000-0000-0000-000000000010' AS UUID),
       (SELECT id FROM app_users WHERE email = 'demo@remiyu.local'),
       'ADMIN'
WHERE '${seed_enabled}' = 'true'
  AND EXISTS (SELECT 1 FROM workspaces WHERE id = CAST('10000000-0000-0000-0000-000000000010' AS UUID))
  AND NOT EXISTS (
    SELECT 1 FROM workspace_members
    WHERE workspace_id = CAST('10000000-0000-0000-0000-000000000010' AS UUID)
      AND user_id = (SELECT id FROM app_users WHERE email = 'demo@remiyu.local')
  );

INSERT INTO import_runs (id, workspace_id, filename, new_messages, duplicate_messages, ai_provider, status, created_at)
SELECT CAST('10000000-0000-0000-0000-000000000020' AS UUID),
       CAST('10000000-0000-0000-0000-000000000010' AS UUID),
       'whatsapp-operasional-oktober.txt', 12, 0, 'mockoon', 'NEEDS_REVIEW', CURRENT_TIMESTAMP
WHERE '${seed_enabled}' = 'true'
  AND EXISTS (SELECT 1 FROM workspaces WHERE id = CAST('10000000-0000-0000-0000-000000000010' AS UUID))
  AND NOT EXISTS (SELECT 1 FROM import_runs WHERE id = CAST('10000000-0000-0000-0000-000000000020' AS UUID));

INSERT INTO import_runs (id, workspace_id, filename, new_messages, duplicate_messages, ai_provider, status, created_at)
SELECT CAST('10000000-0000-0000-0000-000000000021' AS UUID),
       CAST('10000000-0000-0000-0000-000000000010' AS UUID),
       'whatsapp-operasional-pembaruan.txt', 8, 2, 'mockoon', 'NEEDS_REVIEW', CURRENT_TIMESTAMP
WHERE '${seed_enabled}' = 'true'
  AND EXISTS (SELECT 1 FROM workspaces WHERE id = CAST('10000000-0000-0000-0000-000000000010' AS UUID))
  AND NOT EXISTS (SELECT 1 FROM import_runs WHERE id = CAST('10000000-0000-0000-0000-000000000021' AS UUID));

INSERT INTO tasks (id, workspace_id, import_id, title, description, assignee_name, due_at, priority, status, source_message_ids, created_at, updated_at)
SELECT CAST('10000000-0000-0000-0000-000000000101' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000021' AS UUID), 'Finalisasi materi peluncuran', 'Satukan deck presentasi, copy, dan materi visual.', 'Nadia', CURRENT_TIMESTAMP + INTERVAL '5' HOUR, 'HIGH', 'IN_PROGRESS', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000102' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000021' AS UUID), 'Cek kebutuhan vendor', 'Pastikan kebutuhan booth sesuai revisi terakhir.', 'Dimas', CURRENT_TIMESTAMP + INTERVAL '1' DAY, 'HIGH', 'TODO', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000103' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000021' AS UUID), 'Konfirmasi PIC registrasi', 'Tetapkan PIC dan bagikan alur kedatangan peserta.', 'Sinta', CURRENT_TIMESTAMP + INTERVAL '1' DAY, 'HIGH', 'TODO', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000104' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000020' AS UUID), 'Review landing page versi final', 'Periksa tautan, formulir, dan CTA sebelum dipublikasikan.', 'Raka', CURRENT_TIMESTAMP + INTERVAL '2' HOUR, 'HIGH', 'IN_PROGRESS', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000105' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000020' AS UUID), 'Perbarui daftar peserta', 'Gabungkan daftar peserta sementara dengan pendaftaran terbaru.', 'Sinta', CURRENT_TIMESTAMP + INTERVAL '2' DAY, 'MEDIUM', 'TODO', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000106' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000020' AS UUID), 'Susun alur briefing tim', 'Buat agenda, pembagian peran, dan catatan keputusan.', 'Nadia', CURRENT_TIMESTAMP + INTERVAL '3' DAY, 'MEDIUM', 'TODO', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000107' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000020' AS UUID), 'Siapkan banner acara', 'Ekspor desain yang sudah disetujui untuk kebutuhan cetak.', 'Raka', CURRENT_TIMESTAMP + INTERVAL '3' DAY, 'MEDIUM', 'TODO', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000108' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000021' AS UUID), 'Tindak lanjuti anggaran tambahan', 'Kirim ringkasan kebutuhan dan tunggu persetujuan.', 'Nadia', CURRENT_TIMESTAMP + INTERVAL '2' DAY, 'MEDIUM', 'IN_PROGRESS', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000109' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000020' AS UUID), 'Validasi stok merchandise', 'Bandingkan stok vendor dengan jumlah peserta terbaru.', 'Dimas', CURRENT_TIMESTAMP + INTERVAL '4' DAY, 'LOW', 'TODO', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000110' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000020' AS UUID), 'Buat daftar kontak darurat', 'Kumpulkan nomor vendor, venue, dan PIC internal.', 'Sinta', CURRENT_TIMESTAMP + INTERVAL '5' DAY, 'LOW', 'TODO', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000111' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000021' AS UUID), 'Kirim pengingat ke peserta', 'Kirim pengingat kehadiran dan lokasi acara.', 'Sinta', CURRENT_TIMESTAMP + INTERVAL '6' DAY, 'MEDIUM', 'TODO', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000112' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000020' AS UUID), 'Siapkan checklist hari-H', 'Catat pembukaan venue, registrasi, konsumsi, dan penutupan.', 'Dimas', CURRENT_TIMESTAMP + INTERVAL '6' DAY, 'MEDIUM', 'TODO', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000113' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000020' AS UUID), 'Review copy pengumuman', 'Cek nama acara, waktu, tautan, dan gaya bahasa.', 'Nadia', CURRENT_TIMESTAMP - INTERVAL '1' DAY, 'MEDIUM', 'DONE', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000114' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000020' AS UUID), 'Buat folder materi bersama', 'Atur struktur folder desain, dokumen, dan laporan.', 'Raka', CURRENT_TIMESTAMP - INTERVAL '2' DAY, 'LOW', 'DONE', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000115' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000021' AS UUID), 'Catat blocker vendor', 'Tulis keputusan yang masih menunggu jawaban vendor.', 'Dimas', NULL, 'HIGH', 'IN_PROGRESS', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000116' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000020' AS UUID), 'Rancang rundown awal', 'Susun urutan acara sebagai bahan review tim.', 'Sinta', CURRENT_TIMESTAMP + INTERVAL '7' DAY, 'MEDIUM', 'DRAFT', '[]', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true';

INSERT INTO agenda_entries (id, workspace_id, import_id, title, starts_at, status, source_message_ids, created_at)
SELECT CAST('10000000-0000-0000-0000-000000000201' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000021' AS UUID), 'Review progres harian', CURRENT_TIMESTAMP + INTERVAL '2' HOUR, 'CONFIRMED', '[]', CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000202' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000020' AS UUID), 'Briefing tim peluncuran', CURRENT_TIMESTAMP + INTERVAL '1' DAY, 'CONFIRMED', '[]', CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000203' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000020' AS UUID), 'Final check vendor', CURRENT_TIMESTAMP + INTERVAL '2' DAY, 'CONFIRMED', '[]', CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000204' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000020' AS UUID), 'Dry run alur registrasi', CURRENT_TIMESTAMP + INTERVAL '4' DAY, 'CONFIRMED', '[]', CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000205' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000021' AS UUID), 'Rapat koordinasi hari-H', CURRENT_TIMESTAMP + INTERVAL '6' DAY, 'CONFIRMED', '[]', CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true'
UNION ALL SELECT CAST('10000000-0000-0000-0000-000000000206' AS UUID), CAST('10000000-0000-0000-0000-000000000010' AS UUID), CAST('10000000-0000-0000-0000-000000000020' AS UUID), 'Evaluasi pasca peluncuran', CURRENT_TIMESTAMP + INTERVAL '10' DAY, 'DRAFT', '[]', CURRENT_TIMESTAMP WHERE '${seed_enabled}' = 'true';
